   770	export default function App() {
   771	  const [showSplash, setShowSplash] = useState(true);
   772	  const [selectedEvent, setSelectedEvent] = useState(null);
   773	  const scrollPositionRef = useRef(0);
   774	
   775	  useEffect(() => {
   776	    const timer = setTimeout(() => {
   777	      setShowSplash(false);
   778	    }, 3000);
   779	    return () => clearTimeout(timer);
